<div class="dr-filters"><div class="dr-grid"><div><label>Año académico</label><select id="dr-year" class="form-control form-control-sm"><option value="">Todos</option><?php foreach($years as $x):?><option value="<?php echo(int)$x['id'];?>" <?php echo $activeYear===(int)$x['id']?'selected':''; ?>><?php echo htmlspecialchars($x['year'].($x['is_active']?' (Activo)':''));?></option><?php endforeach;?></select></div><div><label>Nivel</label><select id="dr-level" class="form-control form-control-sm"><option value="">Todos</option><option>Inicial</option><option>Primaria</option><option>Secundaria</option></select></div><div><label>Grado</label><select id="dr-grade" class="form-control form-control-sm" disabled><option value="">Seleccione un nivel</option></select></div><div><label>Sección</label><select id="dr-section" class="form-control form-control-sm"><option value="">Todas</option><?php foreach(['U','A','B','C','D','E','F'] as $x):?><option><?php echo$x;?></option><?php endforeach;?></select></div><div><label>Estudiante</label><select id="dr-student" class="form-control form-control-sm dr-select2"><option value="">Todos</option><?php foreach($students as $x):?><option value="<?php echo(int)$x['id'];?>"><?php echo htmlspecialchars($x['id_no'].' - '.$x['name']);?></option><?php endforeach;?></select></div><div><label>Concepto</label><select id="dr-course" class="form-control form-control-sm dr-select2"><option value="">Todos</option><?php foreach($courses as $x):?><option value="<?php echo(int)$x['id'];?>"><?php echo htmlspecialchars($x['course'].' · '.$x['level'].' · '.($x['year']?:'Sin año'));?></option><?php endforeach;?></select></div><div><label>Estado financiero</label><select id="dr-financial" class="form-control form-control-sm"><option value="Con deuda" selected>Con deuda</option><option value="">Todos</option><?php foreach(['Pendiente','Parcial','Pagada','Exonerada','Vencida','Suspendida','Anulada'] as $x):?><option><?php echo$x;?></option><?php endforeach;?></select></div><div><label>Estado de deuda</label><select id="dr-debt-status" class="form-control form-control-sm"><option value="">Todos</option><option>Activa</option><option>Suspendida</option><option>Anulada</option></select></div><div><label>Estado del estudiante</label><select id="dr-student-status" class="form-control form-control-sm"><option value="">Todos</option><option>Activo</option><option>Retirado</option><option>Egresado</option></select></div><div><label>Filtrar fechas por</label><select id="dr-date-type" class="form-control form-control-sm"><option value="assignment">Asignación</option><option value="due">Vencimiento</option><option value="payment">Pago confirmado</option></select></div><div><label>Desde</label><input id="dr-from" type="date" class="form-control form-control-sm"></div><div><label>Hasta</label><input id="dr-to" type="date" class="form-control form-control-sm"></div><div class="d-flex align-items-end"><button id="dr-apply" class="btn btn-primary btn-sm mr-2"><i class="fas fa-filter mr-1"></i>Aplicar</button><button id="dr-clear" class="btn btn-light border btn-sm">Restablecer</button></div></div></div>
<div class="dr-stats"><div class="dr-stat"><small>Monto original</small><strong id="dr-original">—</strong></div><div class="dr-stat"><small>Descuentos/exoneraciones</small><strong class="text-info" id="dr-discounts">—</strong></div><div class="dr-stat"><small>Total exigible</small><strong id="dr-effective">—</strong></div><div class="dr-stat"><small>Total cobrado aplicable</small><strong class="text-success" id="dr-collected">—</strong></div><div class="dr-stat"><small>Saldo pendiente</small><strong class="text-danger" id="dr-balance">—</strong></div><div class="dr-stat"><small>Saldo vencido</small><strong class="text-danger" id="dr-overdue">—</strong></div></div>
