<div class="modal fade" id="debt-print-modal" tabindex="-1" role="dialog" aria-hidden="true"><div class="modal-dialog modal-xl" style="max-width:96vw"><div class="modal-content"><div class="modal-header py-2"><h5 class="modal-title"><i class="fas fa-print text-primary mr-2"></i>Vista previa del reporte</h5><button class="close" data-dismiss="modal"><span>&times;</span></button></div><div class="modal-body p-0" style="height:82vh"><div id="dr-print-loading" class="h-100 d-flex align-items-center justify-content-center text-muted"><i class="fas fa-spinner fa-spin mr-2"></i>Preparando reporte...</div><iframe id="dr-print-frame" style="display:none;width:100%;height:100%;border:0"></iframe></div></div></div></div>
<script>
$(function(){
const activeYear=<?php echo (int)$activeYear; ?>,gradeMap={Inicial:['3 años','4 años','5 años'],Primaria:['1°','2°','3°','4°','5°','6°'],Secundaria:['1°','2°','3°','4°','5°']};
if($.fn.select2)$('.dr-select2').select2({width:'100%'});
function loadGrades(value){let level=$('#dr-level').val(),grades=gradeMap[level]||[],select=$('#dr-grade').empty();if(!level){select.append('<option value="">Seleccione un nivel</option>').prop('disabled',true);return}select.append('<option value="">Todos</option>');grades.forEach(g=>select.append(new Option(g,g)));select.prop('disabled',false);if(value&&grades.indexOf(value)>=0)select.val(value)}
$('#dr-level').on('change',function(){loadGrades('')});loadGrades('');
function filters(){return{academic_year_id:$('#dr-year').val(),nivel:$('#dr-level').val(),grado:$('#dr-grade').val(),seccion:$('#dr-section').val(),student_id:$('#dr-student').val(),concepto:$('#dr-course').val(),financial_status:$('#dr-financial').val(),debt_status:$('#dr-debt-status').val(),student_status:$('#dr-student-status').val(),date_type:$('#dr-date-type').val(),start_date:$('#dr-from').val(),end_date:$('#dr-to').val()}}
function money(v){return'S/ '+Number(v||0).toFixed(2)}
let table=$('#debt-reports-table').DataTable({serverSide:true,processing:true,pageLength:25,lengthMenu:[[25,50,100],[25,50,100]],order:[[0,'asc']],columnDefs:[{orderable:false,targets:[1]}],ajax:{url:'api/debt_reports.php',data:function(d){return $.extend(d,filters())},dataSrc:function(json){$('#dr-error').addClass('d-none');let s=json.summary||{};$('#dr-original').text(money(s.original));$('#dr-discounts').text(money(s.discounts));$('#dr-effective').text(money(s.effective));$('#dr-collected').text(money(s.collected));$('#dr-balance').text(money(s.balance));$('#dr-overdue').text(money(s.overdue));return json.data||[]},error:function(xhr){let m='No se pudo cargar el reporte.';try{let j=JSON.parse(xhr.responseText);m=j.error||j.message||m}catch(e){}$('#dr-error').removeClass('d-none').text(m)}},language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_',processing:'Cargando deudas...',zeroRecords:'No se encontraron deudas pendientes',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Sin registros',paginate:{previous:'Anterior',next:'Siguiente'}}});
$('#dr-apply').click(function(){table.ajax.reload()});
$('#dr-clear').click(function(){$('.dr-filters input').val('');$('.dr-filters select').val('').trigger('change');$('#dr-year').val(String(activeYear));$('#dr-financial').val('Con deuda');$('#dr-date-type').val('assignment');loadGrades('');table.search('').ajax.reload()});
function query(){return $.param(filters())}$('#dr-export').click(function(){location.href='export_debt_report.php?'+query()});$('#dr-print').click(function(){let frame=$('#dr-print-frame');$('#dr-print-loading').removeClass('d-none').addClass('d-flex');frame.hide().off('load.dr').on('load.dr',function(){$('#dr-print-loading').removeClass('d-flex').addClass('d-none');frame.show()}).attr('src','print_debt_report.php?'+query());$('#debt-print-modal').modal('show')});$('#debt-print-modal').on('hidden.bs.modal',function(){$('#dr-print-frame').attr('src','about:blank').hide()});
});
</script>
